<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { getAccountList } from '@/api/account'
import { getOrderMatrixDetail, newRequestId, previewReturnShipment, queryOrderMatrix, recordReturnShipment, updateOrderNote, type MatrixOrder, type ReturnShipmentCommand } from '@/api/matrix'
import { useModalFocusTrap } from '@/composables/useModalFocusTrap'
import type { Account } from '@/types'
import { showError, showSuccess } from '@/utils'

const route=useRoute(),router=useRouter(),loading=ref(false),accounts=ref<Account[]>([]),orders=ref<MatrixOrder[]>([]),total=ref(0),summary=ref<Record<string,any>>({}),dataset=ref<Record<string,any>>({}),notice=ref('')
const routeAccountId=Number(route.query.accountId)
const routePage=Number(route.query.page)
const page=ref(Number.isSafeInteger(routePage)&&routePage>0?routePage:1)
const filter=reactive({search:String(route.query.search||''),accountId:Number.isSafeInteger(routeAccountId)&&routeAccountId>0?routeAccountId:undefined as number|undefined,orderStatus:String(route.query.orderStatus||''),deliveryStatus:String(route.query.deliveryStatus||''),refundStatus:String(route.query.refundStatus||'ALL'),startDate:String(route.query.startDate||''),endDate:String(route.query.endDate||'')})
const selected=ref<Record<string,any>|null>(null),detailLoading=ref(false),activeTab=ref<'overview'|'refund'|'logistics'|'timeline'|'message'>('overview'),noteSaving=ref(false),noteForm=reactive({flag:'NONE',note:''})
const detailReturnScroll=ref(0)
const returnDialog=ref(false),returnSaving=ref(false),returnPreview=ref<Record<string,any>|null>(null),returnRefund=ref<Record<string,any>|null>(null)
const returnForm=reactive<ReturnShipmentCommand>({requestId:'',direction:'BUYER_TO_SELLER',logisticsCompanyCode:'',logisticsCompanyName:'',trackingNumber:'',shipmentStatus:'IN_TRANSIT',latestEvent:'',shippedTime:'',receivedTime:'',platformConfirmed:false,confirmationText:''})
useModalFocusTrap(returnDialog,()=>document.querySelector<HTMLElement>('.return-shipment-dialog'))
const totalPages=computed(()=>Math.max(1,Math.ceil(total.value/20)))
const money=(v:unknown)=>v===null||v===undefined?'—':`¥ ${Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}`
const text=(v:unknown)=>v===null||v===undefined||v===''?'—':String(v)
const time=(v:unknown)=>v?new Date(String(v)).toLocaleString('zh-CN'):'—'
const label=(v?:string)=>({WAIT_BUYER_PAY:'待付款',PAID:'已付款',TO_SHIP:'待发货',SHIPPED:'已发货',COMPLETED:'已完成',PENDING:'待处理',PROCESSING:'处理中',RETRY_WAIT:'等待重试',REVIEW_REQUIRED:'需人工核对',FAILED:'失败',SUCCESS:'成功',UNKNOWN:'结果未知',NONE:'无退款',REQUESTED:'退款申请',APPROVED:'已同意',REJECTED:'已拒绝',DISPUTE:'争议中',FULL:'完整',PARTIAL:'部分',UNSYNCED:'未同步',READY:'可用',NOT_VERIFIED:'尚未验证',READY_AUTOMATION:'可自动评价',WAITING_ORDER_STATE:'等待订单状态',LOCAL_AUTOMATION_ONLY:'仅本地提醒',READY_LOCAL_EVIDENCE:'可记录平台事实',UNAVAILABLE:'不可用',READ_ONLY:'只读',BUYER_TO_SELLER:'买家退回',SELLER_TO_BUYER:'卖家补发/换货',PENDING_PICKUP:'待揽收',IN_TRANSIT:'运输中',DELIVERED:'已送达',RECEIVED:'已签收',EXCEPTION:'物流异常',RETURNED:'已退回',REFUND_ONLY:'仅退款',RETURN_REFUND:'退货退款',EXCHANGE:'换货',RED:'红色',ORANGE:'橙色',YELLOW:'黄色',GREEN:'绿色',BLUE:'蓝色',PURPLE:'紫色'}[v||'']||v||'未知')
const tone=(v?:string)=>['COMPLETED','SUCCESS','FULL','SHIPPED','READY_AUTOMATION','RECEIVED','DELIVERED'].includes(v||'')?'good':['FAILED','REVIEW_REQUIRED','DISPUTE','REJECTED','EXCEPTION','RETURNED'].includes(v||'')?'bad':['PARTIAL','PROCESSING','RETRY_WAIT','REQUESTED','PENDING_PICKUP','IN_TRANSIT'].includes(v||'')?'warn':'muted'
const eventLabel=(v?:string)=>({ORDER_CREATED:'订单创建',ORDER_STATUS_CHANGED:'订单状态变化',DELIVERY_STATUS_CHANGED:'履约状态变化',REFUND_STATUS_CHANGED:'退款状态变化',RETURN_SHIPMENT_RECORDED:'售后运单已记录',ORDER_NOTE_UPDATED:'协作备注已更新',AUTO_DELIVERY_STARTED:'自动发货开始',AUTO_DELIVERY_SUCCEEDED:'自动发货成功',AUTO_DELIVERY_FAILED:'自动发货失败',MESSAGE_RECEIVED:'收到买家消息',MESSAGE_SENT:'卖家消息已发送'}[v||'']||'其他订单事件')
const outcomeLabel=(v?:string)=>({LOCAL_SUCCESS:'本地处理成功',PLATFORM_CONFIRMED:'平台已确认',PLATFORM_REQUESTED:'已请求平台',MANUAL_PLATFORM_CONFIRMED:'人工核对平台事实',UNKNOWN:'结果未知',FAILED:'失败',SUCCEEDED:'成功',CANCELLED:'已取消'}[v||'']||'状态待核对')
const sourceLabel=(v?:string)=>({LOCAL:'本地记录',LOCAL_EVENT:'本地事件',LOCAL_AUTOMATION:'本地自动化',LOCAL_OR_IMPORTED_SNAPSHOT:'本地或导入快照',MANUAL_PLATFORM_CONFIRMATION:'人工平台核对',PLATFORM_API:'平台接口',PLATFORM_WEB:'平台页面',WEBHOOK:'平台事件',SYSTEM:'系统任务',NONE:'来源未同步'}[v||'']||'其他来源')
const capabilityLabel=(v:string|number)=>({virtualDelivery:'虚拟商品自动发货',physicalShipmentWrite:'实物发货写入',logisticsTracking:'物流跟踪',rating:'订单评价',returnTracking:'售后物流记录',refundDecision:'退款决策',dispute:'争议处理',orderNote:'协作备注',orderPriceChange:'订单改价',receiptReminder:'收货提醒',platformWrite:'平台写入'}[String(v)]||'其他订单能力')
const capabilityDescription=(cap:Record<string,any>)=>{const raw=String(cap?.reason||cap?.source||'');const mapped:{[key:string]:string}={LOCAL:'由本地协作能力提供',LOCAL_AUTOMATION:'由本地自动化提供',LOCAL_OR_IMPORTED_SNAPSHOT:'依据本地或导入的订单快照判断',NOT_VERIFIED:'当前尚未获得平台验证',ORDER_STATE_NOT_READY:'当前订单状态尚不满足执行条件'};return mapped[raw]||raw||'按当前订单状态和已同步证据动态判断'}
const localizeOrderDetail=(detail:Record<string,any>|null)=>{if(!detail)return detail;detail.timeline=(detail.timeline||[]).map((event:Record<string,any>)=>({...event,rawEventType:event.eventType||event.description,rawOutcomeState:event.outcomeState||event.operationStatus,rawDataSource:event.dataSource||'LOCAL',eventType:eventLabel(event.eventType||event.description),outcomeState:outcomeLabel(event.outcomeState||event.operationStatus),dataSource:sourceLabel(event.dataSource||'LOCAL')}));detail.capabilityItems=Object.entries(detail.capabilities||{}).filter(([,cap])=>cap!==null&&typeof cap==='object'&&Object.prototype.hasOwnProperty.call(cap,'status')).map(([key,cap])=>({key,...cap as Record<string,any>}));return detail}
const syncOrderRoute=()=>router.replace({query:{...route.query,search:filter.search.trim()||undefined,accountId:filter.accountId?String(filter.accountId):undefined,orderStatus:filter.orderStatus||undefined,deliveryStatus:filter.deliveryStatus||undefined,refundStatus:filter.refundStatus==='ALL'?undefined:filter.refundStatus,startDate:filter.startDate||undefined,endDate:filter.endDate||undefined,page:page.value===1?undefined:String(page.value)}})
const load=async()=>{loading.value=true;void syncOrderRoute();try{const result=await queryOrderMatrix({search:filter.search||undefined,accountIds:filter.accountId?[filter.accountId]:undefined,orderStatus:filter.orderStatus||undefined,deliveryStatus:filter.deliveryStatus||undefined,refundStatus:filter.refundStatus,startDate:filter.startDate||undefined,endDate:filter.endDate||undefined,page:page.value,pageSize:20});orders.value=result.data?.records||[];total.value=result.data?.total||0;summary.value=result.data?.summary||{};dataset.value=result.data?.dataset||{};notice.value=result.data?.dataNotice||''}catch(e:any){showError(e.message||'订单工作台加载失败')}finally{loading.value=false}}
const apply=()=>{page.value=1;void load()}
const appScrollRoot=()=>document.querySelector<HTMLElement>('.app-main')
const setOrderTab=(tab:string)=>{activeTab.value=tab as typeof activeTab.value;void router.replace({query:{...route.query,detailTab:activeTab.value}})}
const openDetail=async(item:Pick<MatrixOrder,'orderRecordId'>,fromDeepLink=false)=>{if(!fromDeepLink)detailReturnScroll.value=appScrollRoot()?.scrollTop||0;detailLoading.value=true;const requestedTab=String(route.query.detailTab||'overview');activeTab.value=(['overview','refund','logistics','timeline','message'].includes(requestedTab)?requestedTab:'overview') as typeof activeTab.value;await router.replace({query:{...route.query,orderRecordId:String(item.orderRecordId),detailTab:activeTab.value}});try{const result=await getOrderMatrixDetail(item.orderRecordId);selected.value=localizeOrderDetail(result.data||null);noteForm.flag=selected.value?.order?.flag||'NONE';noteForm.note=selected.value?.order?.note||''}catch(e:any){showError(e.message||'订单详情加载失败')}finally{detailLoading.value=false}}
const closeDetail=async()=>{const scrollTop=detailReturnScroll.value;selected.value=null;await router.replace({query:{...route.query,orderRecordId:undefined,detailTab:undefined}});await nextTick();appScrollRoot()?.scrollTo({top:scrollTop})}
useModalFocusTrap(computed(()=>Boolean(selected.value||detailLoading.value)),()=>document.querySelector<HTMLElement>('.order-drawer'),()=>void closeDetail())
const saveNote=async()=>{if(!selected.value?.order?.orderRecordId)return;noteSaving.value=true;try{const result=await updateOrderNote(selected.value.order.orderRecordId,{requestId:newRequestId('order-note'),flag:noteForm.flag,note:noteForm.note});selected.value.order=result.data?.order||selected.value.order;showSuccess('订单备注已保存');await load()}finally{noteSaving.value=false}}
const openMessage=()=>{const order=selected.value?.order;if(!order)return;router.push({path:'/messages',query:{accountId:String(order.accountId),sessionId:order.sessionId||'',buyerId:order.buyerId||''}})}
const refreshDetail=async()=>{if(!selected.value?.order?.orderRecordId)return;const currentTab=activeTab.value;const result=await getOrderMatrixDetail(selected.value.order.orderRecordId);selected.value=localizeOrderDetail(result.data||null);activeTab.value=currentTab}
const openReturnShipment=(refund:Record<string,any>)=>{returnRefund.value=refund;returnPreview.value=null;Object.assign(returnForm,{requestId:newRequestId('return-shipment'),direction:'BUYER_TO_SELLER',logisticsCompanyCode:'',logisticsCompanyName:'',trackingNumber:'',shipmentStatus:'IN_TRANSIT',latestEvent:'',shippedTime:'',receivedTime:'',platformConfirmed:false,confirmationText:''});returnDialog.value=true}
const shipmentPayload=():ReturnShipmentCommand=>({...returnForm,logisticsCompanyCode:returnForm.logisticsCompanyCode||undefined,latestEvent:returnForm.latestEvent||undefined,shippedTime:returnForm.shippedTime?new Date(returnForm.shippedTime).toISOString():undefined,receivedTime:returnForm.receivedTime?new Date(returnForm.receivedTime).toISOString():undefined})
const previewShipment=async()=>{if(!returnRefund.value)return;returnSaving.value=true;try{const result=await previewReturnShipment(returnRefund.value.refundCaseId,shipmentPayload());returnPreview.value=result.data||null;returnForm.confirmationText=returnPreview.value?.confirmationText||''}catch(e:any){returnPreview.value=null;showError(e.message||'售后运单预检失败')}finally{returnSaving.value=false}}
const saveReturnShipment=async()=>{if(!returnRefund.value||!returnPreview.value)return;returnSaving.value=true;try{await recordReturnShipment(returnRefund.value.refundCaseId,shipmentPayload());showSuccess('已记录闲鱼平台确认的售后运单');returnDialog.value=false;await refreshDetail();await load()}catch(e:any){showError(e.message||'售后运单记录失败')}finally{returnSaving.value=false}}
watch(activeTab,tab=>{if(selected.value)void router.replace({query:{...route.query,detailTab:tab}})})
watch(selected,value=>{if(value)return;const hadDetail=Boolean(route.query.orderRecordId);if(!hadDetail)return;const scrollTop=detailReturnScroll.value;void router.replace({query:{...route.query,orderRecordId:undefined,detailTab:undefined}}).then(()=>nextTick()).then(()=>appScrollRoot()?.scrollTo({top:scrollTop}))})
onMounted(async()=>{const result=await getAccountList();accounts.value=result.data?.accounts||[];await load();const orderRecordId=Number(route.query.orderRecordId);if(Number.isSafeInteger(orderRecordId)&&orderRecordId>0)await openDetail({orderRecordId},true)})
</script>

<template>
  <main class="workbench order-matrix" :aria-busy="loading">
    <header class="workbench__header"><div><h1>订单与售后</h1><p>跨店查询履约、退款、物流和评价；平台事实与本地处理状态分开展示。</p></div><button class="workbench__btn" :disabled="loading" @click="load">{{ loading?'刷新中':'刷新' }}</button></header>
    <section class="order-matrix__metrics"><article><span>筛选订单</span><strong>{{ summary.orderCount??'—' }}</strong><small>当前结果范围</small></article><article><span>成交金额</span><strong>{{ money(summary.gmv) }}</strong><small>已知金额 {{ summary.knownAmountCount??'—' }} 单</small></article><article><span>待履约</span><strong>{{ summary.pendingDeliveryCount??'—' }}</strong><small>待处理 / 重试中</small></article><article><span>退款处理中</span><strong>{{ summary.refundingCount??'—' }}</strong><small>已知退款 {{ money(summary.refundAmount) }}</small></article><article><span>数据覆盖</span><strong>{{ label(summary.coverageStatus) }}</strong><small>{{ dataset.coveredAccountCount??'—' }}/{{ dataset.accountCount??'—' }} 个店铺</small></article></section>
    <div class="order-matrix__notice"><strong>数据说明</strong><span>{{ notice||'订单金额或退款未采集时保持为空。' }}</span><time>最近成功 {{ time(dataset.lastSuccessTime) }}</time></div>
    <section class="workbench__card order-matrix__panel"><div class="order-matrix__toolbar"><input v-model="filter.search" class="workbench__input" placeholder="订单号、买家、商品或运单号" @keyup.enter="apply"><select v-model="filter.accountId" class="workbench__select" @change="apply"><option :value="undefined">全部可见店铺</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{ a.accountNote||a.unb }}</option></select><select v-model="filter.deliveryStatus" class="workbench__select" @change="apply"><option value="">全部履约状态</option><option value="PENDING">待履约</option><option value="PROCESSING">处理中</option><option value="RETRY_WAIT">等待重试</option><option value="REVIEW_REQUIRED">人工核对</option><option value="FAILED">失败</option><option value="SUCCESS">成功</option></select><select v-model="filter.refundStatus" class="workbench__select" @change="apply"><option value="ALL">全部退款状态</option><option value="NONE">无退款</option><option value="REQUESTED">退款申请</option><option value="PROCESSING">处理中</option><option value="APPROVED">已同意</option><option value="REJECTED">已拒绝</option><option value="DISPUTE">争议中</option></select><input v-model="filter.startDate" class="workbench__input" type="date" aria-label="开始日期"><input v-model="filter.endDate" class="workbench__input" type="date" aria-label="结束日期"><button class="workbench__btn workbench__btn--primary" @click="apply">查询</button></div>
      <div class="order-matrix__table"><table><thead><tr><th>订单 / 店铺</th><th>商品 / 买家</th><th>金额</th><th>订单状态</th><th>履约</th><th>退款</th><th>数据证据</th><th></th></tr></thead><tbody><tr v-for="item in orders" :key="item.orderRecordId" :class="{exception:item.hasException}" @click="openDetail(item)"><td><strong>{{ item.orderId }}</strong><small>{{ item.accountName||`店铺 ${item.accountId}` }}</small></td><td><strong>{{ item.goodsTitle||item.goodsId||'商品未知' }}</strong><small>{{ item.buyerName||'买家未知' }}</small></td><td><strong>{{ money(item.amount) }}</strong><small>{{ item.amount==null?'金额未采集':item.currency||'CNY' }}</small></td><td><span :class="['status',tone(item.orderStatus)]">{{ label(item.orderStatus) }}</span><small>{{ time(item.createdTime) }}</small></td><td><span :class="['status',tone(item.deliveryStatus)]">{{ label(item.deliveryStatus) }}</span></td><td><span :class="['status',tone(item.refundStatus)]">{{ label(item.refundStatus) }}</span></td><td><strong>{{ sourceLabel(item.dataSource) }}</strong><small>{{ label(item.coverageStatus) }} · {{ time(item.lastSyncedTime) }}</small></td><td><button class="row-action" @click.stop="openDetail(item)">详情</button></td></tr></tbody></table><div v-if="!loading&&!orders.length" class="order-matrix__empty">当前范围没有订单记录。</div></div><footer class="order-matrix__pagination"><span>共 {{ total }} 条</span><div><button :disabled="page<=1" @click="page--;load()">上一页</button><b>{{ page }} / {{ totalPages }}</b><button :disabled="page>=totalPages" @click="page++;load()">下一页</button></div></footer></section>
    <div v-if="selected||detailLoading" class="order-drawer__backdrop" @click.self="selected=null"><aside class="order-drawer" role="dialog" aria-modal="true" aria-labelledby="order-title" tabindex="-1"><div v-if="detailLoading" class="order-drawer__loading">正在读取订单事实…</div><template v-else-if="selected"><header><div><p>{{ selected.order.accountName||`店铺 ${selected.order.accountId}` }}</p><h2 id="order-title">订单 {{ selected.order.orderId }}</h2><small>{{ selected.order.goodsTitle||selected.order.goodsId||'商品未知' }} · {{ selected.order.buyerName||'买家未知' }}</small></div><button aria-label="关闭" @click="selected=null">×</button></header><nav role="tablist" aria-label="订单详情栏目"><button v-for="tab in [{k:'overview',n:'概览'},{k:'logistics',n:'物流'},{k:'refund',n:`退款 ${selected.refunds?.length?selected.refunds.length:(selected.order.refundStatus==='NONE'?'0':'· 未同步')}`},{k:'message',n:`消息 ${selected.messages?.length||0}`},{k:'timeline',n:`时间线 ${selected.timeline?.length||0}`} ]" :key="tab.k" role="tab" :aria-selected="activeTab===tab.k" :class="{active:activeTab===tab.k}" @click="activeTab=tab.k as any">{{ tab.n }}</button></nav><div class="order-drawer__body"><template v-if="activeTab==='overview'"><section class="order-facts"><div><span>金额</span><strong>{{ money(selected.order.amount) }}</strong></div><div><span>订单状态</span><strong>{{ label(selected.order.orderStatus) }}</strong></div><div><span>履约状态</span><strong>{{ label(selected.order.deliveryStatus) }}</strong></div><div><span>评价能力</span><strong>{{ label(selected.capabilities?.rating?.status) }}</strong></div></section><section class="drawer-card"><h3>本地协作备注</h3><label>旗帜<select v-model="noteForm.flag" class="workbench__select"><option v-for="f in ['NONE','RED','ORANGE','YELLOW','GREEN','BLUE','PURPLE']" :key="f" :value="f">{{ label(f) }}</option></select></label><label>备注<textarea v-model="noteForm.note" class="workbench__textarea" maxlength="1000"></textarea></label><button class="workbench__btn workbench__btn--primary" :disabled="noteSaving" @click="saveNote">保存备注</button></section><section class="drawer-card"><h3>能力边界</h3><div class="capability-grid"><article v-for="cap in selected.capabilityItems" :key="cap.key"><strong>{{ capabilityLabel(cap.key) }}</strong><span :class="['status',tone(cap.status)]">{{ label(cap.status) }}</span><p>{{ capabilityDescription(cap) }}</p></article></div></section></template><template v-else-if="activeTab==='logistics'"><section class="drawer-card"><h3>物流事实</h3><dl><div><dt>物流公司</dt><dd>{{ text(selected.order.logisticsCompanyName) }}</dd></div><div><dt>运单号</dt><dd>{{ text(selected.order.trackingNumber) }}</dd></div><div><dt>物流状态</dt><dd>{{ text(selected.order.logisticsStatus) }}</dd></div><div><dt>最近事件</dt><dd>{{ text(selected.order.logisticsLastEvent) }}</dd></div></dl><p>系统不在没有平台确认的情况下伪造实物发货成功。</p></section></template><template v-else-if="activeTab==='refund'"><section v-if="selected.refunds?.length" class="refund-list"><article v-for="refund in selected.refunds" :key="refund.refundCaseId" class="drawer-card refund-case"><header><div><span class="eyebrow">{{ label(refund.afterSalesType||refund.type) }}</span><h3>{{ refund.refundId||`售后记录 ${refund.refundCaseId}` }}</h3></div><span :class="['status',tone(refund.platformStatus)]">{{ label(refund.platformStatus) }}</span></header><div class="refund-case__facts"><div><span>申请金额</span><strong>{{ money(refund.requestedAmount) }}</strong></div><div><span>已同意金额</span><strong>{{ money(refund.approvedAmount) }}</strong></div><div><span>退货进度</span><strong>{{ label(refund.returnStatus) }}</strong></div><div><span>平台下一步</span><strong>{{ text(refund.platformActionRequired) }}</strong></div></div><p class="refund-case__reason">{{ refund.reason||'退款原因未同步' }}</p><div class="deadline-strip"><span>卖家处理截止<strong>{{ time(refund.sellerDecisionDeadline||refund.decisionDeadline) }}</strong></span><span>买家寄回截止<strong>{{ time(refund.buyerReturnDeadline) }}</strong></span></div><p v-if="refund.latestStatusMessage" class="latest-event">{{ refund.latestStatusMessage }}</p><div v-if="refund.returnShipments?.length" class="return-shipment-list"><article v-for="shipment in refund.returnShipments" :key="shipment.returnShipmentId"><header><strong>{{ label(shipment.direction) }} · {{ shipment.logisticsCompanyName }}</strong><span :class="['status',tone(shipment.shipmentStatus)]">{{ label(shipment.shipmentStatus) }}</span></header><code>{{ shipment.trackingNumber }}</code><p>{{ shipment.latestEvent||'暂无物流事件' }}</p><small>发出 {{ time(shipment.shippedTime) }} · 签收 {{ time(shipment.receivedTime) }}</small><small>{{ sourceLabel(shipment.source) }} · {{ label(shipment.coverageStatus) }} · 同步 {{ time(shipment.syncedAt) }}</small></article></div><div v-else class="refund-case__empty">尚未同步或记录退货/换货运单，不能据此判断没有物流。</div><details v-if="refund.actions?.length" class="refund-actions"><summary>查看 {{ refund.actions.length }} 条售后处理记录</summary><ol><li v-for="action in refund.actions" :key="action.actionId"><strong>{{ eventLabel(action.actionType) }}</strong><span>{{ outcomeLabel(action.outcomeState) }}</span><p>{{ action.reason||'无补充说明' }}</p><small>{{ action.operatorUsername||'系统' }} · {{ time(action.createdTime) }} · {{ action.requestId }}</small></li></ol></details><footer><small>{{ sourceLabel(refund.source) }} · {{ label(refund.coverageStatus) }} · 更新 {{ time(refund.updatedTime) }}</small><button v-if="selected.capabilities?.returnTracking?.status==='READY_LOCAL_EVIDENCE'" class="workbench__btn" @click="openReturnShipment(refund)">记录平台已确认运单</button></footer></article></section><div v-else class="refund-empty-state"><strong>{{ selected.order.refundStatus==='NONE'?'未发现退款案例':'退款状态尚未形成可核验案例' }}</strong><p>{{ selected.order.refundStatus==='NONE'?'当前证据范围显示无退款；后续平台同步可能更新。':'订单列表存在退款状态，但详情案例尚未同步，不能显示为 0，也不能据此执行售后动作。' }}</p><button class="workbench__btn" @click="refreshDetail">重新读取订单事实</button></div></template><template v-else-if="activeTab==='message'"><section class="drawer-card message-list"><article v-for="(m,index) in selected.messages" :key="index"><strong>{{ m.senderName||m.senderId||'未知发送者' }}</strong><p>{{ m.content||m.msgContent||'[非文本消息]' }}</p><small>{{ time(m.messageTime||m.storedAt) }}</small></article></section></template><template v-else><ol class="timeline"><li v-for="(event,index) in selected.timeline" :key="index"><i></i><div><strong>{{ event.eventType||event.description }}</strong><p>{{ event.outcomeState||event.operationStatus }} · {{ event.dataSource||'LOCAL' }}</p><small>{{ time(event.createdTime||event.createdTimeEpochMs) }}</small><details><summary>脱敏高级详情与机器码</summary><pre>{{ JSON.stringify({eventType:event.rawEventType||event.eventType,outcomeState:event.rawOutcomeState||event.outcomeState,dataSource:event.rawDataSource||event.dataSource,requestId:event.requestId||null,platformRequestId:event.platformRequestId||null},null,2) }}</pre></details></div></li></ol></template></div><footer><button class="workbench__btn" @click="openMessage">查看买家会话</button><button class="workbench__btn workbench__btn--primary" @click="selected=null">完成查看</button></footer></template></aside></div>
    <div v-if="returnDialog" class="return-dialog__backdrop" @click.self="returnDialog=false"><section class="return-shipment-dialog" role="dialog" aria-modal="true" aria-labelledby="return-shipment-title" tabindex="-1"><header><div><span class="eyebrow">售后物流证据</span><h2 id="return-shipment-title">记录平台已确认的运单</h2><p>订单 {{ selected?.order?.orderId }} · {{ returnRefund?.refundId||`售后记录 ${returnRefund?.refundCaseId}` }}</p></div><button aria-label="关闭售后运单弹窗" @click="returnDialog=false">×</button></header><div class="return-dialog__body"><div class="safety-note" role="note"><strong>不会向闲鱼提交退货、换货或退款决定</strong><span>请先在闲鱼确认真实运单，再把事实记录到矩阵，供多人协作和审计使用。</span></div><div class="return-form"><label>物流方向<select v-model="returnForm.direction" class="workbench__select" data-autofocus @change="returnPreview=null"><option value="BUYER_TO_SELLER">买家退回</option><option value="SELLER_TO_BUYER">卖家补发 / 换货</option></select></label><label>物流状态<select v-model="returnForm.shipmentStatus" class="workbench__select" @change="returnPreview=null"><option v-for="status in ['PENDING_PICKUP','IN_TRANSIT','DELIVERED','RECEIVED','EXCEPTION','RETURNED']" :key="status" :value="status">{{ label(status) }}</option></select></label><label>物流公司<input v-model.trim="returnForm.logisticsCompanyName" class="workbench__input" maxlength="128" placeholder="例如：顺丰速运" @input="returnPreview=null"></label><label>物流公司代码（选填）<input v-model.trim="returnForm.logisticsCompanyCode" class="workbench__input" maxlength="64" placeholder="例如：SF" @input="returnPreview=null"></label><label class="return-form__wide">运单号<input v-model.trim="returnForm.trackingNumber" class="workbench__input" maxlength="128" autocomplete="off" placeholder="请输入已在闲鱼确认的运单号" @input="returnPreview=null"></label><label>发出时间（选填）<input v-model="returnForm.shippedTime" class="workbench__input" type="datetime-local" @change="returnPreview=null"></label><label>签收时间（选填）<input v-model="returnForm.receivedTime" class="workbench__input" type="datetime-local" @change="returnPreview=null"></label><label class="return-form__wide">最近物流事件（选填）<textarea v-model.trim="returnForm.latestEvent" class="workbench__textarea" maxlength="500" rows="3" placeholder="例如：买家已寄回，等待商家签收" @input="returnPreview=null"></textarea></label></div><section v-if="returnPreview" class="return-preview"><header><strong>确认范围</strong><span>{{ label(returnPreview.direction) }} · {{ label(returnPreview.shipmentStatus) }}</span></header><p>{{ returnPreview.confirmationText }}</p><dl><div><dt>平台写入</dt><dd>未执行</dd></div><div><dt>本次保存</dt><dd>本地事实与审计证据</dd></div></dl><label class="platform-confirm"><input v-model="returnForm.platformConfirmed" type="checkbox">我已在闲鱼核对该订单、方向、物流公司和运单号，确认以上是平台已存在的真实事实。</label></section></div><footer><button class="workbench__btn" @click="returnDialog=false">取消</button><button v-if="!returnPreview" class="workbench__btn workbench__btn--primary" :disabled="returnSaving||!returnForm.logisticsCompanyName||returnForm.trackingNumber.length<4" @click="previewShipment">生成确认范围</button><button v-else class="workbench__btn workbench__btn--primary" :disabled="returnSaving||!returnForm.platformConfirmed" @click="saveReturnShipment">{{ returnSaving?'记录中':'记录已确认事实' }}</button></footer></section></div>
  </main>
</template>
